class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def ladoos(root, home, K):
    def find_node(node, target):
        if not node:
            return None
        if node.val == target:
            return node
        left = find_node(node.left, target)
        if left:
            return left
        return find_node(node.right, target)

    def collect_ladoos(node, k):
        if not node or k < 0:
            return 0
        return node.val + collect_ladoos(node.left, k - 1) + collect_ladoos(node.right, k - 1)

    def traverse_and_collect(node, target, k, distance):
        if not node:
            return 0, False
        if node.val == target:
            return collect_ladoos(node, k), True
        left_sum, found_in_left = traverse_and_collect(node.left, target, k, distance + 1)
        if found_in_left:
            return left_sum + (node.val if k - distance > 0 else 0) + collect_ladoos(node.right, k - distance - 1), True
        right_sum, found_in_right = traverse_and_collect(node.right, target, k, distance + 1)
        if found_in_right:
            return right_sum + (node.val if k - distance > 0 else 0), True
        return 0, False

    home_node = find_node(root, home)
    if not home_node:
        return home
    total_ladoos, _ = traverse_and_collect(root, home, K, 0)
    return total_ladoos
